query OccurrenceCatalogNumberFacet($q: String, $predicate: Predicate, $size: Int, $include: String){
  search: occurrenceSearch(q: $q, predicate: $predicate) {
    cardinality {
      total: recordedBy
    }
    facet {
      field: recordedBy(size: $size, include: $include) {
        name: key
        count
      }
    }
  }
}
